// FullTable AI landing assistant → Archie AI (Core Services › Archie AI, aiChat, project default model).
// Lives in src/client (survivor zone) because only this zone and src/infrastructure/archie may import the SDK;
// src/presentation may import src/client. Hand-placed file, not regenerated by the platform.
import { useCallback } from "react";
import { useArchieClient } from "@archie/react-sdk";

/** Returns ask({ system, messages, maxTokens }) → reply text. Throws on any failure so the caller can fall back. */
export function useLandingAssistant() {
  const client = useArchieClient();
  return useCallback(
    async ({ system, messages, maxTokens }) => {
      const res = await client.ai.chat({ system, messages, maxTokens });
      const text = (res && Array.isArray(res.content) ? res.content : [])
        .filter((p) => p && p.type === "text" && typeof p.text === "string")
        .map((p) => p.text)
        .join("")
        .trim();
      if (!text) throw new Error("Archie AI returned no text");
      return text;
    },
    [client],
  );
}
